"""Independent regression checks and Spanish handoff for second cleanup."""
import hashlib
import math
import subprocess
from collections import Counter
from second_structural_cleanup import ROOT,OUT,MODEL,FE,BASE,STREAM,read,write,old,sha

def main():
    model=read(MODEL); now={s['id']:s for s in model['solids']}; before={s['id']:s for s in old(MODEL)['solids']}
    fe=read(FE); qa=read(OUT/'review_qa.json'); checks=qa['checks']; audit=read(OUT/'GLOBAL_BEAM_FRAGMENTATION_AUDIT.json');pairs=read(OUT/'confirmed_beam_pairs.json');stacks=read(OUT/'COLUMN_VERTICAL_STACKS.json')
    def check(k,v):checks[k]='PASS' if v else 'FAIL'
    moved=[r for st in stacks['stacks'] for r in st['rows'] if r['decision']=='ALIGN_PRIMARY_CONFIRMED']
    check('COLUMN_XY_TARGET',all(math.dist(now[r['id']]['center'][:2],r['target_xy'])<1e-8 for r in moved))
    check('COLUMN_Z_SECTION_MATERIAL_PRESERVED',all(now[g]['center'][2]==s['center'][2] and all(now[g].get(k)==s.get(k) for k in ('width_m','depth_m','height_m','section_width_m','section_depth_m','material')) for g,s in before.items() if s['category']=='column'))
    check('STABLE_GLOBAL_AXES',model['globalAxisSystem']==old(MODEL)['globalAxisSystem'])
    check('STACK_VERTICALITY',all(max(math.dist(now[a]['center'][:2],now[b]['center'][:2]) for a in st['member_ids'] for b in st['member_ids'])<.001 for st in stacks['stacks'] if st['confirmed']))
    lengths=[]
    for plan in pairs['merge_plans']:
        gid=plan['canonical']; es=[e for e in fe['elements'] if e['element_id']==gid];nodes=fe['nodes']
        ll=[math.dist([nodes[str(e['node_i'])][k] for k in ('x','y','z')],[nodes[str(e['node_j'])][k] for k in ('x','y','z')]) for e in es]
        lengths.append({'id':gid,'FE_segments':len(es),'geometry_length_m':math.dist(now[gid]['start'],now[gid]['end']),'FE_length_m':sum(ll),'residual_m':abs(sum(ll)-math.dist(now[gid]['start'],now[gid]['end'])),'minimum_segment_m':min(ll) if ll else 0})
    check('MERGED_BEAM_LENGTHS_NO_MICROSEGMENTS',all(r['residual_m']<.002 and r['minimum_segment_m']>.02 for r in lengths))
    edges=[(e['building'],min(e['node_i'],e['node_j']),max(e['node_i'],e['node_j'])) for e in fe['elements']]
    check('NO_DUPLICATE_FE_MEMBER',len(edges)==len(set(edges)))
    nodekeys=[(n['building'],n['x'],n['y'],n['z']) for n in fe['nodes'].values()]
    check('NO_DUPLICATE_FE_NODE',len(nodekeys)==len(set(nodekeys)))
    expected={'P1L4_FINAL':'56e24ac0568b24eba3cf119f2e3cc66fc0af3a35','P1L3_DELIVERED':'c847c131512d00cc85bb95aa5719278d70da0c2b','entregap1l2':'d2e40be4292b2a55b2e0db8be6be51cd31535bd6'}
    check('DELIVERED_TAGS_PRESERVED',all(subprocess.check_output(['git','rev-parse',k+'^{commit}'],cwd=ROOT,text=True).strip()==v for k,v in expected.items()))
    paths=subprocess.check_output(['git','diff','--name-only',BASE],cwd=ROOT,text=True).splitlines()
    check('HISTORICAL_RESULT_INPUTS_UNCHANGED',not any(p.startswith('entregas/P1L3/results/') and not p.startswith('entregas/P1L3/results/post_p1l3_candidate/') for p in paths))
    checks['BEAM_FRAGMENTATION']='PASS_WITH_NOTE';checks['COLUMN_ALIGNMENT']='PASS_WITH_NOTE'
    checks.setdefault('UNITY_COMPILE','PENDING');checks.setdefault('UNITY_PLAY','PENDING')
    ranges={'<=1cm':0,'1–5cm':0,'5–10cm':0,'>10cm':0}
    for r in moved:
        d=r['displacement_m']; ranges['<=1cm' if d<=.01 else '1–5cm' if d<=.05 else '5–10cm' if d<=.1 else '>10cm']+=1
    qa.update(beam_length_checks=lengths,column_displacement_distribution=ranges,column_stacks_reviewed=stacks['stack_count'],columns_reviewed=stacks['columns_audited'],columns_aligned=len(moved),new_beam_pairs_merged=len(pairs['merge_plans']),geometry_sha256=sha(MODEL),fe_sha256=sha(FE))
    write(OUT/'review_qa.json',qa)
    changes=read(OUT/'current_review_changes.json');changes['rows']=[r for r in changes['rows'] if r['type']!='REVIEW_REQUIRED']
    for st in stacks['stacks']:
        if not st['confirmed']:
            for row in st['rows']:changes['rows'].append({'id':row['id'],'type':'REVIEW_REQUIRED','reason':'Cadena sin suficientes controles superiores únicos; no se movió. '+row.get('reason',''),'source':'COLUMN_VERTICAL_STACKS.json','historical_ids':[row['id']]})
    write(OUT/'current_review_changes.json',changes);write(STREAM/'current_review_changes.json',changes)
    # Regenerate constraint graph from current IDs; no normalization or solver.
    parent={int(n):int(n) for n in fe['nodes']}
    def find(n):
        while parent[n]!=n:parent[n]=parent[parent[n]];n=parent[n]
        return n
    for c in fe['constraints']:parent[find(c['slave_node'])]=find(c['master_node'])
    groups={}
    for n in parent:groups.setdefault(find(n),[]).append(n)
    write(OUT/'current_constraint_clusters.json',{'fe_version':sha(FE),'status':'RIGID_IDEALIZATION_REVIEW_REQUIRED_NOT_RUN','clusters':[{'nodes':ns,'members_with_both_ends_inside':[e['element_id'] for e in fe['elements'] if e['node_i'] in ns and e['node_j'] in ns]} for ns in groups.values() if len(ns)>1]})
    md=['# Saneamiento estructural 2 — revisión PRE-P1L5','',f'Base histórica de esta revisión: `{BASE}`. Rama `codex/post-p1l4-structural-audit`. Commit evaluable del checkpoint: consultar el commit que contiene este archivo (`git log -1 --format=%H -- entregas/PRE_P1L5/second_structural_cleanup/REVIEW_STATUS.md`).','', '**Checkpoint geométrico para revisión. PRE_P1L5_BASELINE: BLOCKED.** No se ejecutó OpenSees, no se recalcularon cargas/resultados y no se inició P1L5.','', '## Muros y apoyos','', '44 muros ED1 excluidos por decisión de alcance: **cero activos**. Esto no significa que el edificio real no tenga muros ni certifica la resistencia del modelo sin ellos. Se archivó su geometría.','', 'Se retiraron siete apoyos visuales exclusivos de muro y 13 restricciones de base exclusivas de muro del candidato FE. Se preservaron los 19 apoyos visuales de columnas, los ocho compartidos y las restricciones de base de todas las columnas. Apoyos UNKNOWN: ninguno. Los apoyos generados de columnas siguen su nuevo XY; no se trasladaron cimentaciones levantadas en terreno.','', 'Detalle de los 34 apoyos ED1: [ED1_WALL_SCOPE_REMOVAL_AUDIT](../ED1_WALL_SCOPE_REMOVAL_AUDIT.md).','', '## Vigas','',f"{audit['beams_audited']} vigas inspeccionadas; {len(audit['candidates'])} pares candidatos; {len(audit['chains'])} cadenas candidatas de tres miembros. Se fusionaron 16 pares nuevos (32 fragmentos → 16 vigas); sumando las dos fusiones anteriores: 18 pares históricos corregidos. No se fusionó una cadena de tres sin evidencia completa.",'','| ID canónico | ID absorbido | Gap original m | Motivo de conservar ID |','|---|---|---:|---|']
    for p in pairs['merge_plans']:md.append(f"| {p['canonical']} | {', '.join(p['merged_from'])} | {p['evidence']['gap_m']:.6f} | Etiqueta directa; luego tramo histórico más largo |")
    md+=['', 'Otros 51 pares no se fusionaron: 26 sin caras continuas inequívocas; 19 con anotaciones de abertura/junta o indicios CAD de apoyo que requieren resolver la llamada; cinco con apoyo físico intermedio; uno con altura inferida. No se afirma que los 51 sean discontinuidades reales.','',f"Se detectaron {len(audit['microsegments'])} miembros menores de 0.30 m; no se borraron por longitud. Las 16 vigas fusionadas tienen longitud FE concordante dentro de 0.4 mm y ningún segmento nuevo menor de 2 cm.",'','## Columnas y patrón 18,13 cm','',f"143 columnas revisadas, {stacks['stack_count']} grupos de continuidad. 74 ajustes XY: {ranges}. Máximo {max(r['displacement_m'] for r in moved):.6f} m. 36 ajustes son menores de 0.1 mm. Se preservaron Z, dimensiones, sección y material. 14 columnas en 12 grupos siguen en revisión; no se forzó su alineación.",'','La prueba usa LINE de RLE-EJES, no inserciones de texto: P1 transforma el eje 1 a −0.000030 m; P2 a +0.181358 m; P3/P4 a +0.181341/+0.181321 m. La diferencia de registro P1→P2 es +0.181388 m. S1 incorpora columnas inferidas desde P1, por eso hereda ese desfase aunque su propia planta tenga otro origen. No son decenas de transferencias independientes.','', 'Además, el extractor promediaba extremos de segmentos: al cortar una cara o subdividirla en varias líneas, desplazaba el centro. Ejemplos primarios: P1 C002 (cara incompleta), C013 (cara cortada), C021/C022 (fragmentos asimétricos), P2 C004/C010 (cara superior subdividida). Se reconstruyó el centro entre caras opuestas o del rectángulo cerrado y se contrastó cada arista con handles del DXF.','', '**Referencia adoptada:** contorno primario P2 de cada stack y controles de P3/P4. Se alinearon únicamente columnas y apoyos visuales generados de esas columnas; no se trasladaron plantas completas ni se alteraron ejes globales o transformaciones 700 aprobadas. La diferencia de ~0.181 m entre ese registro de columnas y los ejes globales nominales permanece explícita; debe reconciliarse antes de aprobar cargas/FE. No debe presentarse como calce global resuelto.','', 'P1 C023 conserva su dimensión geométrica previa, aunque el rectángulo principal CAD es distinto; está marcado `UNCHANGED_DIMENSIONS_REVIEW_REQUIRED`, no se cambió la sección durante esta operación.','', '## Controles externos','', 'Santiago aporta columnas con continuidad por pisos en el snapshot c1f434b; para una estación como E1-S1-C004 su XY normalizado previo es (37.47,0.18), cercano al piso superior nuestro. Cáceres aporta la retícula manual vertical: C-8 normalizada a (37.49,0.18). Ambas son pistas concordantes, no prueba métrica: las transformaciones externas originales siguen siendo ajustes de nube de puntos candidatos. Los movimientos se decidieron por contornos/ejes propios. No hubo escritura ni ejecución de código en los repositorios externos.','', '## Candidato reconstruido','', '676 miembros; 1183 nodos; 1205 restricciones; 33 apoyos FE; siete relaciones geometría→varios segmentos FE. Seis geometrías sin camino a apoyo / cuatro componentes. No se ha validado su formulación rígida ni ejecutado el solver.','', 'Pendientes: '+', '.join(qa['summary']['pending_ids'])+'. `E1-S1-V-005` es nuevo tras retirar su sistema de muros; no se le inventó apoyo. La reducción 22→6 no es prueba de mejor comportamiento resistente: principalmente refleja el cambio de alcance.','', '## Unity','', 'Abrir `entregas/P1L3/José/viewer_unity`, `Assets/Main.unity`, Play. Modelo actual sin muros ED1; resultados actuales NONE. Diagnóstico → Cambios de esta revisión muestra WALL_REMOVED / WALL_SUPPORT_REMOVED / BEAM_MERGED / COLUMN_ALIGNED / REVIEW_REQUIRED. Diagnóstico → COLUMN STACKS aísla cada cadena, permite apagar S1/P1/P2/P3/P4 y usar vistas XZ/YZ. R vuelve al edificio.','', '## QA','']+[f'- {k}: {v}' for k,v in checks.items()]
    md+=['','## Fuentes vigentes','', '- Geometría ED1: `entregas/P1L2/unity_export/model_1_audited_corrected.json`.','- Geometría ED2: `entregas/P1L2/unity_export/model_2_viewer.json`.','- Contrato conjunto: `entregas/P1L2/unity_export/model_combined_viewer.json`.','- FE candidato: `entregas/P1L3/results/post_p1l3_candidate/analysis_model_post_p1l3_candidate.json`.','- Datos auditables: `wall_scope_audit.json`, `GLOBAL_BEAM_FRAGMENTATION_AUDIT.json`, `COLUMN_VERTICAL_STACKS.json`, `confirmed_beam_pairs.json`, `review_qa.json`.','- Receptores: `current_tributary_receptor_crosswalk.json`, elegibilidad únicamente; cargas no aplicadas.','', 'Regeneración segura después del checkpoint: build_combined_model.py → enrich_combined_model.py → build_post_p1l3_topology_candidate.py → build_unity_bundle.py → report_second_cleanup.py → build/Play QA. Las migraciones --apply-walls y apply_second_geometry.py están protegidas contra reaplicación; no se deben repetir sobre CURRENT. Los informes de propuesta documentan el estado previo, no deben sobrescribirse con una nueva auditoría post-migración.']
    (OUT/'REVIEW_STATUS.md').write_text('\n'.join(md)+'\n',encoding='utf-8')
    bmd=['# Auditoría global de fragmentación de vigas','',f"{audit['beams_audited']} vigas, {len(audit['candidates'])} candidatos, 16 pares fusionados; 51 pendientes de interpretación primaria. Tolerancias y endpoints completos en `second_structural_cleanup/GLOBAL_BEAM_FRAGMENTATION_AUDIT.json`.",'','[Resultados, IDs canónicos y gaps](second_structural_cleanup/REVIEW_STATUS.md).','', '| A | B | Gap m | Ángulo ° | dZ m | Decisión |','|---|---|---:|---:|---:|---|']
    for r in audit['candidates']:bmd.append(f"| {r['beam_A']} | {r['beam_B']} | {r['gap_m']:.6f} | {r['angle_deg']:.6f} | {r['z_difference_m']:.6f} | {r['decision']} |")
    bmd+=['','## Cadenas candidatas','']+[', '.join(c['ids'])+' — revisión, no fusión por transitividad.' for c in audit['chains']]
    (ROOT/'entregas/PRE_P1L5/GLOBAL_BEAM_FRAGMENTATION_AUDIT.md').write_text('\n'.join(bmd)+'\n',encoding='utf-8')
    print('SECOND_CLEANUP_QA',checks);assert 'FAIL' not in checks.values()
if __name__=='__main__':main()
